package com.agacostays.payment.service.impl; import com.agacostays.payment.dto.request.VerifyPaymentRequest; import com.agacostays.payment.entity.Payment; import com.agacostays.payment.exception.BusinessRuleException; import com.agacostays.payment.service.*; import org.springframework.stereotype.Service;
@Service public class PaymentVerificationServiceImpl implements PaymentVerificationService { private final PaymentGatewayService gateway; public PaymentVerificationServiceImpl(PaymentGatewayService g){this.gateway=g;} public void verify(Payment p,VerifyPaymentRequest r){if(!p.getGatewayOrderId().equals(r.gatewayOrderId()))throw new BusinessRuleException("Gateway order does not belong to payment"); if(!gateway.verifySignature(r.gatewayOrderId(),r.gatewayPaymentId(),r.gatewaySignature()))throw new BusinessRuleException("Invalid payment signature");} }
